WITH valid AS (SELECT id, shipped_date, delivered_date, cost, status, CASE WHEN cost >= 83 THEN 'High' WHEN cost >= 22 THEN 'Medium' ELSE 'Low' END AS cost_level FROM shipments WHERE shipped_date > TO_DATE('2023-03-18') AND carrier IS NOT NULL) SELECT id, shipped_date, cost, status, LEAD(cost, 1) OVER (PARTITION BY status ORDER BY shipped_date, id) AS next_cost, ROW_NUMBER() OVER (ORDER BY delivered_date DESC, id) AS event_seq FROM valid;
